protected void new()
{
    super(classStr(AVAProdStartService), methodStr(AVAProdStartService, process), SysOperationExecutionMode::Synchronous);
}

public static AVAProdStartController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAProdStartController controller;
    controller = new AVAProdStartController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVATraverseTrans   travTrans = _args.record();
    AVAProdStartController controller;
    controller = AVAProdStartController::construct();
    AVAProdStartContract contract = controller.getDataContractObject();
    contract.parmTraverseNum(travTrans.TravNum);
    controller.parmArgs(_args);
    controller.startOperation();
}
